'use client';

import { useState } from 'react';

interface Course {
  id: string;
  name: string;
  description?: string;
  image?: string;
}

interface CourseSelectorModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (courseId: string) => void;
  courses: Course[];
}

export default function CourseSelectorModal({ isOpen, onClose, onSelect, courses }: CourseSelectorModalProps) {
  const [search, setSearch] = useState('');

  if (!isOpen) return null;

  const filtered = courses.filter((c) =>
    c.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-2xl shadow-xl max-w-2xl w-full mx-4 max-h-[80vh] flex flex-col"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
          <h2 className="text-lg font-semibold text-[#1a1a1a]">Select a Course</h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 transition-colors"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Search */}
        <div className="px-6 py-3 border-b border-gray-100">
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search courses..."
            className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm focus:outline-none focus:border-[#9F80DA] transition-colors"
          />
        </div>

        {/* Course grid */}
        <div className="flex-1 overflow-y-auto p-6">
          {filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-gray-400">
              <svg className="w-10 h-10 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
              <p className="text-sm">No courses found</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-4">
              {filtered.map((course) => (
                <div
                  key={course.id}
                  className="border border-gray-100 rounded-xl overflow-hidden hover:border-[#9F80DA]/30 transition-colors"
                >
                  <div className="h-28 bg-gradient-to-br from-[#9F80DA]/10 to-[#9F80DA]/5 flex items-center justify-center">
                    {course.image ? (
                      <img src={course.image} alt={course.name} className="w-full h-full object-cover" />
                    ) : (
                      <svg className="w-8 h-8 text-[#9F80DA]/40" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                      </svg>
                    )}
                  </div>
                  <div className="p-3">
                    <h3 className="text-sm font-medium text-[#1a1a1a] truncate">{course.name}</h3>
                    {course.description && (
                      <p className="text-xs text-gray-500 mt-1 line-clamp-2">{course.description}</p>
                    )}
                    <button
                      onClick={() => onSelect(course.id)}
                      className="mt-3 w-full text-sm font-medium text-[#9F80DA] border border-[#9F80DA]/30 rounded-lg py-1.5 hover:bg-[#9F80DA]/5 transition-colors"
                    >
                      Select
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
